from qbc_aitpraml import Cat, challenge

C = Cat("AIG",
        industries=["all"],
        jurisdictions=["US-federal", "US-states", "EU"],
        products=["all-echelon-products"])

AGENT_FACT = ("Echelon repositories carry instruction files for several AI coding agents (AGENTS.md, CLAUDE.md, GEMINI.md) "
              "and Praxis provenance records contributions by AI agents (for example openai/codex in "
              "echelon-due-diligence AGENTS.md front matter), so AI coding agents are in active engineering use.")

# ---------------- Answer units ----------------
C.au(1, title="AI system and AI use inventory, including AI used to build and operate the service",
     status="unknown",
     rationale="No AI inventory for Echelon was located. Unbound requirements call for an agent capability manifest (AIN-002) and mapping of agent catalogs (UNB-AGT-001), but these are product requirements, not an enterprise inventory. " + AGENT_FACT,
     target="Echelon maintains one machine-readable AI inventory generated from configuration rather than assembled by hand. Each entry names the AI system or use (product feature, internal assistant, AI coding agent, operations agent), its owner, model provider and model version, prompt and tool versions, data classes it may access, tenants in scope, authority ceiling from the authority matrix, and the risk assessment that approved it. Product agents are registered through the capability manifest that the tool broker enforces, so an agent that is not in the inventory cannot obtain tools. Engineering agents are registered through Praxis execution identity. Customers receive a tenant-specific extract on request.",
     current="Unknown; no inventory located. AI coding agents are used in engineering (see status rationale) but are not recorded in a governed inventory with data-access scope.",
     intended="Build the inventory from the Unbound agent capability manifest (AIN-002), Praxis execution identity records and the vendor inventory, and reconcile them on every release.",
     provable="Nothing for an inventory. Praxis provenance can show which agent identities contributed to repositories that use it.",
     statement="Echelon has not yet established a formal AI inventory. AI coding agents are used to develop Echelon software. Echelon plans to maintain a configuration-generated inventory covering product AI features and internal AI use, with a customer-specific extract.",
     kind="not-available",
     controls=[1, 2], evrs=[1, 2],
     requirements=["AIN-002", "UNB-AGT-001", "SOC2-017"],
     freshness="per-event", mechanism="not-defined", automation="high",
     impl_cost="low", rec_cost="low",
     owner="Not assigned (proposed: Echelon AI governance owner)",
     residual=["Personal use of consumer AI tools by staff or contractors outside managed accounts would not appear in a configuration-generated inventory."],
     open=["Which AI providers and accounts are used today for engineering work, and under which commercial terms?"])

C.au(2, title="AI policy, accountable ownership and acceptable use",
     status="unknown",
     rationale="No adopted AI policy was located. Business plan section 10.03 (AI governance) is a draft whose text is a generic template shared with other sections and contains no AI-specific rules. The only security policy located (Secure Construction Standard v0.1, proposed) contains no AI rule.",
     target="A board- or owner-approved AI policy states permitted and prohibited AI uses, the rule that AI may recommend and prepare but never hold human-authority operations or clear risk concerns (NoAiClearance), data handling rules for AI tools (no customer data in unmanaged tools), an accountable AI risk owner, an exception process with expiry, and AI literacy training for every person and agent operator. The policy is versioned in source control and its rules are enforced where possible by the tool broker and authority matrix rather than by attestation.",
     current="Not established. Governance invariants exist in design artifacts (Echelon AI-Native Enterprise Design Framework AGENTS.md: AI never clears under NoAiClearance; agents never hold human-authority operations) but these are framework rules, not an adopted organizational policy.",
     intended="Draft an AI policy from the existing invariants (EDF AGENTS.md, CNV-AIO-001, GOV-AUTH-003) and the Unbound authority tiers A0 to A5, and adopt it formally.",
     provable="Nothing for an adopted policy. The design invariants are visible in repository text and, for the EDF, in property tests.",
     statement="Echelon does not yet have a formally adopted AI policy. Its design rules already state that AI may recommend and prepare but may not approve, clear risk concerns or hold human-authority operations; Echelon plans to adopt these as policy.",
     kind="planned",
     controls=[3], evrs=[3],
     requirements=["CNV-AIO-001", "GOV-AUTH-003", "SOC2-017"],
     freshness="P1Y", mechanism="periodic-manual", automation="partial",
     impl_cost="low", rec_cost="low",
     owner="Not assigned (proposed: Echelon managing member)",
     residual=["A policy is only as strong as its enforcement; rules not encoded in the tool broker rely on human compliance."],
     open=["Who is the accountable AI risk owner for Echelon Foundry?"])

C.au(3, title="Alignment with NIST AI RMF and ISO/IEC 42001, and independent assessment of AI governance",
     status="proposed-target-state",
     rationale="No mapping or certification exists. Unbound requirements (SOC2-017, AIN-027, RR-AIN-027-r1) describe controls that would map to NIST AI RMF functions, but no crosswalk has been produced and no assessment has occurred.",
     target="Echelon publishes a crosswalk from its AI controls to the NIST AI RMF functions and the Generative AI Profile, ISO/IEC 42001 Annex A and the CSA AI Controls Matrix, generated from the control register so it cannot drift. Each mapped control links to continuously produced evidence. Echelon decides on ISO/IEC 42001 certification by customer demand and cost, and in the meantime offers the crosswalk plus SOC 2 coverage of agent controls (SOC2-017) as its assurance path.",
     current="No crosswalk, no certification, no external assessment.",
     intended="Produce the crosswalk once AI controls exist in the control register; evaluate ISO/IEC 42001 certification after SOC 2 readiness.",
     provable="Nothing.",
     statement="Echelon is not certified to ISO/IEC 42001 and has not been independently assessed on AI governance. It plans to publish a control crosswalk to the NIST AI RMF and ISO/IEC 42001 once its AI controls are implemented.",
     kind="planned",
     controls=[4], evrs=[4],
     requirements=["SOC2-017", "SOC2-035"],
     freshness="P1Y", mechanism="not-defined", automation="high",
     impl_cost="medium", rec_cost="medium",
     owner="Not assigned (proposed: Echelon compliance owner)",
     challenge=challenge(
         intent="Customers want confidence that AI risk is governed by a recognized, complete method rather than ad hoc choices.",
         adverse="An AI failure (wrong eligibility finding, data leak, unauthorized action) that a structured program would have anticipated.",
         conv_eff="Management system certification shows that a process exists and is followed; it does not show that specific agent controls are effective. It is a periodic point-in-time sample.",
         legal="Not legally required for Echelon. EU AI Act harmonized standards may later make some standards relevant for high-risk systems.",
         contract="Increasingly requested in enterprise questionnaires; rarely a hard contractual requirement yet.",
         history="Mirrors ISO 27001 certification as a procurement shortcut.",
         elim="Several AI risks can be removed structurally: agents with no tools beyond A2 cannot execute consequential actions regardless of governance maturity.",
         auto="Authority matrix, tool broker and adversarial CI suite enforce controls on every run.",
         cont="Control register emits evidence per run; crosswalk generated from it.",
         alt="Continuous evidence of enforced agent limits plus a generated crosswalk, with SOC 2 coverage of SOC2-017, in place of early ISO/IEC 42001 certification.",
         verif="Verifiable by an auditor sampling denial records and adversarial test runs.",
         accept="Uncertain; procurement teams often score certifications as yes or no.",
         invalid="If a large customer contractually requires ISO/IEC 42001 certification, the alternative does not satisfy it.",
         conv_cost="medium to high (certification audit plus management system overhead)",
         alt_cost="low to medium once controls exist",
         alt_risk="A self-produced crosswalk is first-party evidence and may be discounted.",
         pro=["Structural limits address the highest-consequence AI risks directly.", "A generated crosswalk cannot drift from the control register."],
         con=["Certification is independent; the alternative is first-party until audited.", "Procurement scoring may not credit architecture."],
         tech="stronger", inst="uncertain"))

C.au(4, title="AI risk and impact assessment before deployment and on change",
     status="proposed-target-state",
     rationale="Unbound requires security and privacy design review before introducing autonomous permissions (SOC2-030), shadow-mode simulation and adversarial tests before autonomous consequential actions (GOV-AUTH-018), and subgroup false-alert measurement for sanctions matching (CNV-GRT-006). None is implemented and there is no general AI impact assessment method.",
     target="Every AI use passes a recorded risk and impact assessment before activation and on any model, prompt, tool, data or use change. The assessment classifies the use against the authority tiers, identifies affected people (donors, advisors, grantees, staff), evaluates accuracy, bias, security, privacy and misuse, records the regulatory classification (EU AI Act, Colorado AI Act) and names the human decision owner. Assessments for any automated scoring that affects people include measured error rates by relevant subgroup. Activation is refused by the release gate when no current assessment exists.",
     current="Not established.",
     intended="Use the SOC2-030 design review as the gate and extend it with an AI impact template aligned to ISO/IEC 42005 and NIST AI RMF MAP functions.",
     provable="Nothing.",
     statement="Echelon plans to require a documented AI risk and impact assessment before any AI capability is enabled and whenever it materially changes. No such assessments exist yet.",
     kind="planned",
     controls=[5, 6], evrs=[5, 6],
     requirements=["SOC2-030", "GOV-AUTH-018", "CNV-GRT-006", "AIN-027"],
     freshness="per-event", mechanism="event-driven-automated", automation="partial",
     impl_cost="medium", rec_cost="low",
     owner="Not assigned (proposed: Echelon AI governance owner)",
     residual=["Impact on donors and grantees from automated findings may be indirect and hard to measure before production data exists."])

C.au(5, title="AI model and AI provider due diligence",
     status="unknown",
     rationale="No provider due diligence records were located. Unbound vendor requirements (SOC2-013, RR-REQ-X-073-r2, CNV-GOV-002) would apply to AI providers but do not address model-specific diligence.",
     target="AI providers are tiered as vendors and, when they process customer data, as subprocessors. Before adoption Echelon reviews the provider's assurance reports and complementary user entity controls, data retention and training terms, model documentation (system cards, evaluations, known limitations), deprecation policy and incident history. Models are pinned by version; provider-initiated changes trigger the change process and re-run of the frozen evaluation set before production use. Open-weight models are accepted only with a recorded license review and verified artifact provenance.",
     current="Unknown. AI coding agent providers are in use for engineering, but no diligence record was found.",
     intended="Apply the critical-vendor register (RR-REQ-X-073-r2) to AI providers and add model-specific fields.",
     provable="Nothing.",
     statement="Echelon has not yet documented due diligence on its AI providers. It plans to assess AI providers under its vendor program with model-specific checks and to pin model versions in production.",
     kind="not-available",
     controls=[7], evrs=[7],
     requirements=["SOC2-013", "RR-REQ-X-073-r2", "RR-AIN-027-r1"],
     freshness="P1Y", mechanism="periodic-manual", automation="partial",
     impl_cost="low", rec_cost="low",
     owner="Not assigned (proposed: Echelon vendor risk owner)",
     open=["Do the AI providers used for engineering offer version pinning and advance deprecation notice under Echelon's current account terms?"])

C.au(6, title="AI provider data retention, training use and confidentiality terms",
     status="unknown",
     rationale="Business plan section 10.04 states an intent to separate service use, retention, evaluation, training and product improvement rights, but the section body is a generic draft and no provider terms review or customer-facing commitment exists. SOC2-028 requires permitted AI use to be reflected in access, storage, retrieval and exports.",
     target="Echelon commits contractually that customer data is not used to train or fine-tune any model, by Echelon or any provider, without the customer's separate written opt-in, and it uses only provider offerings whose terms prohibit training on inputs and outputs. Echelon records, per provider, prompt and output retention periods, abuse-monitoring human review terms, zero-retention eligibility and processing region, and it selects zero or minimal retention where available. Evaluation sets built from customer data require the same opt-in and are tenant-scoped.",
     current="Unknown; provider terms in use have not been reviewed in a record located here.",
     intended="Record provider terms in the vendor register and publish a customer-facing AI data use statement based on business plan section 10.04.",
     provable="Nothing.",
     statement="Echelon intends not to use customer data to train models and to use only AI provider terms that prohibit training on customer inputs. These terms have not yet been documented or contractually committed.",
     kind="planned",
     controls=[8], evrs=[8],
     requirements=["SOC2-028"],
     freshness="P90D", mechanism="periodic-manual", automation="low",
     impl_cost="low", rec_cost="low",
     owner="Not assigned (proposed: Echelon privacy owner)",
     residual=["Provider abuse-monitoring retention may persist even under no-training terms."],
     open=["Which provider tiers used today offer contractual no-training and zero-retention terms?"])

C.au(7, title="Applicability of AI-specific law (EU AI Act, Colorado AI Act, state automated decision rules, NAIC bulletin)",
     status="requires-external-validation",
     rationale="No applicability analysis exists. Unbound design keeps AI at recommend or prepare (CNV-AIO-001) and reserves consequential decisions to humans or sponsor-approved deterministic rules, which is likely to keep it outside high-risk classifications, but that conclusion requires counsel review and depends on actual use. Regulatory applicability is to be recorded per UNB-REGMAP-001 to 003.",
     target="Echelon maintains, in its regulatory applicability register, one row per AI law with its role (provider, deployer, developer), the assessed classification of each AI use, the facts relied on, counsel review date and the triggers for re-evaluation. For EU AI Act, Echelon records whether any system falls in Article 6 and Annex III, which transparency duties under Article 50 apply and its AI literacy measures under Article 4. For the Colorado AI Act, Echelon records whether any AI use is a substantial factor in a consequential decision and, if so, provides deployers the documentation the law requires. Echelon supports insurer customers' third-party AI oversight under the NAIC model bulletin with documentation and audit cooperation.",
     current="Not assessed.",
     intended="Add AI law rows to the UNB-REGMAP register and obtain counsel review before any customer-facing AI capability ships.",
     provable="Nothing.",
     statement="Echelon has not yet completed a legal applicability analysis of AI-specific laws. Its design keeps AI in a recommending and preparing role, which it expects to be relevant to that analysis, but no conclusion has been reached.",
     kind="not-available",
     controls=[9], evrs=[9],
     requirements=["UNB-REGMAP-001", "UNB-REGMAP-003", "UNB-REGMAP-004", "CNV-AIO-001"],
     freshness="P180D", mechanism="periodic-manual", automation="low",
     impl_cost="medium", rec_cost="low",
     owner="Not assigned (proposed: Echelon counsel)",
     open=["Current effective date and amendment status of the Colorado AI Act (SB 24-205 as amended) as of the analysis date.",
           "Whether any EU customer or EU data subject exposure is planned."])

C.au(8, title="Model risk management support for bank customers (SR 11-7 and OCC 2011-12 expectations applied to vendor models)",
     status="proposed-target-state",
     rationale="Unbound requires deterministic findings to be separated from AI narrative (CNV-AIO-002), model and prompt versioning with frozen evaluation sets (RR-AIN-027-r1) and evidence capture for AI-assisted outputs (RR-UNB-AI-STD-002-r1). These would support customer model validation but are not built, and no model documentation package exists.",
     target="Echelon classifies each quantitative or AI component by whether a bank customer would treat it as a model (for example sanctions match scoring, risk tiering, anomaly detection). For each, Echelon provides a model documentation package: purpose, conceptual design, data and assumptions, limitations, evaluation results on frozen test sets, monitoring metrics and change history, with advance notice of material changes. Deterministic rules are documented as rules, not models. Generative AI used only to draft labeled narrative is documented as a tool that cannot alter findings, which narrows what the customer must validate.",
     current="Not established.",
     intended="Generate model documentation packages through Folio from the model and prompt version records required by RR-AIN-027-r1.",
     provable="Nothing.",
     statement="Echelon plans to provide model documentation and change notice sufficient for bank customers' model risk management where its components meet their model definition. No documentation package exists yet.",
     kind="planned",
     controls=[10], evrs=[10],
     requirements=["CNV-AIO-002", "RR-AIN-027-r1", "RR-UNB-AI-STD-002-r1", "CNV-GRT-006"],
     freshness="per-event", mechanism="event-driven-automated", automation="high",
     impl_cost="medium", rec_cost="low",
     owner="Not assigned (proposed: Unbound product owner)",
     challenge=challenge(
         intent="The bank must show its examiners that every model it relies on, including vendor models, is validated, monitored and governed.",
         adverse="A bank relies on a vendor score it cannot explain or validate, leading to an examination finding or a wrong decision.",
         conv_eff="Classic SR 11-7 validation of a large language model is impractical: conceptual soundness cannot be established for an opaque foundation model and outcomes testing has weak coverage.",
         legal="SR 11-7 is supervisory guidance to banks, not a law binding Echelon; banks apply it to vendor products through contracts.",
         contract="Common in bank vendor contracts as a documentation and cooperation duty.",
         history="Built for statistical credit and market models.",
         elim="Keep generative AI out of any decision path: findings are deterministic and hashed, AI only drafts labeled narrative that cannot alter them (CNV-AIO-002). The validated object becomes the deterministic rule set plus the matcher, which can be tested exhaustively on perturbation suites.",
         auto="Frozen evaluation and perturbation suites run in CI on every change.",
         cont="Per-release evaluation results and subgroup error metrics.",
         alt="Validate the deterministic components and matcher fully; treat the generative component as an untrusted drafting tool with structural containment instead of attempting model validation of it.",
         verif="Verifiable by inspecting that AI output cannot reach the findings section and by re-running published test suites.",
         accept="Uncertain; some model risk teams will still require an inventory entry and validation for any AI component.",
         invalid="If AI output is ever used to rank, score or decide, the containment argument fails and full model risk treatment applies.",
         conv_cost="high (independent validation of AI components)",
         alt_cost="medium",
         alt_risk="Customers may misclassify the drafting tool and still demand validation, creating duplicate work.",
         pro=["Reduces the validation surface to testable deterministic components.", "Matches the AI-never-decides invariant."],
         con=["Examiners may treat any AI in the workflow as model risk regardless of containment.", "Automation bias in humans reading AI narrative is not removed by containment."],
         tech="stronger", inst="uncertain"))

C.au(9, title="Transparency to customers and end users about AI use, including AI-assisted software development",
     status="proposed-target-state",
     rationale="Unbound requires labeling of facts, inferences and AI narrative (AIN-005, CNV-AIO-002), and that AI unavailability not stop deterministic paths (CNV-AIO-001), which supports opt-out. There is no customer-facing AI disclosure and no change notification process. " + AGENT_FACT,
     target="Echelon publishes and keeps current an AI use statement covering product AI features, the providers behind them, the data each receives and the authority each holds, and states plainly that Echelon builds its software largely with AI coding agents under human-controlled review and release gates. AI-generated content is labeled in the product and in donor or grantee communications. Each tenant can disable AI features without losing deterministic functions. New AI features or providers that process tenant data follow the subprocessor notice process.",
     current="No AI use statement. AI coding agents are used in engineering; this has not been formally disclosed in customer materials because none exist.",
     intended="Publish the AI use statement from the AI inventory; implement tenant-level AI disable switch as a configuration flag enforced by the tool broker.",
     provable="Nothing customer-facing.",
     statement="Echelon develops its software largely with AI coding agents. It plans to publish an AI use statement, label AI-generated content in its products, allow customers to disable AI features, and give advance notice of new AI providers that process customer data.",
     kind="planned",
     controls=[11], evrs=[11],
     requirements=["AIN-005", "CNV-AIO-001", "CNV-AIO-002", "UNB-XIN-SAS-011"],
     freshness="per-event", mechanism="event-driven-automated", automation="high",
     impl_cost="low", rec_cost="low",
     disclosure="public",
     owner="Not assigned (proposed: Echelon AI governance owner)",
     residual=["Disclosure of AI-assisted development may reduce acceptance with some buyers; withholding it would be worse."])

