# ---------------- Evidence requirements ----------------
C.evr(1, title="AI inventory snapshot", description="Versioned export of the AI inventory with provider, model version, prompt and tool versions, data classes, tenant scope, authority ceiling and owner, plus reconciliation diff against the prior release.",
      mechanism="event-driven-automated", freshness="per-event", format="JSON",
      fields=["generatedAt", "sourceCommit", "generatorVersion", "entryCount"], signing="Signed build artifact (proposed)", retention="Life of service plus 3 years (proposed)")
C.evr(2, title="Tool broker denial records for unregistered agents", description="Log of tool requests refused because the agent identity is not in the capability manifest.",
      mechanism="continuous-automated", freshness="P1D", format="Append-only event log",
      fields=["agentId", "requestedTool", "decision", "policyVersion", "correlationId"], retention="Per SOC 2 evidence retention (to be set with auditor per SOC2-023)")
C.evr(3, title="Approved AI policy record", description="AI policy document with version, approver, approval date, next review date and acknowledgment records from personnel and agent operators.",
      producer="not yet assigned", mechanism="periodic-manual", freshness="P1Y", format="Markdown in source control with approval record")
C.evr(4, title="AI control crosswalk", description="Generated mapping from Echelon AI controls to external AI frameworks with links to the evidence each control emits.",
      mechanism="event-driven-automated", freshness="per-event", format="CSV and JSON", disclosure="authenticated-prospect")
C.evr(5, title="AI risk and impact assessment record", description="Completed assessment per AI use and per material change: affected parties, authority tier, risks, mitigations, regulatory classification, approver and gate result.",
      mechanism="event-driven-automated", freshness="per-event", format="Structured record linked to release",
      fields=["aiUseId", "changeRef", "assessor", "approver", "decision", "assessedAt"])
C.evr(6, title="Subgroup error report", description="Recall and false-alert rates of automated matching or scoring by relevant subgroup on the versioned test suite, at each change and quarterly.",
      mechanism="periodic-automated", freshness="P90D", format="Report with test suite hash",
      fields=["suiteVersion", "matcherVersion", "thresholds", "runAt"], disclosure="customer-only")
C.evr(7, title="AI provider due diligence file", description="Per provider: assurance report review, CUEC mapping, model documentation reviewed, deprecation and change terms, pinned model versions, evaluation results before version adoption.",
      mechanism="periodic-manual", freshness="P1Y", format="Vendor register entry")
C.evr(8, title="AI provider data terms register", description="Per provider and offering: training prohibition, prompt and output retention, abuse monitoring review terms, zero-retention status, processing regions, contract reference and review date.",
      mechanism="periodic-manual", freshness="P90D", format="Register entry", disclosure="customer-only")
C.evr(9, title="AI law applicability determinations", description="Register rows for each AI law with role, classification, facts, counsel reviewer and date, and re-evaluation triggers.",
      mechanism="periodic-manual", freshness="P180D", format="Register entry", disclosure="nda")
C.evr(10, title="Model documentation package", description="Per model-like component: purpose, design, data, assumptions, limitations, evaluation results, monitoring metrics and change log; with change notices sent to customers.",
       mechanism="event-driven-automated", freshness="per-event", format="Folio PDF and JSON (proposed)", disclosure="customer-only")
C.evr(11, title="AI use statement and tenant AI configuration", description="Published AI use statement version history and per-tenant record of AI features enabled or disabled, with change events.",
       mechanism="event-driven-automated", freshness="per-event", format="Web page plus configuration events", disclosure="public")

# ---------------- Questions ----------------
FIN = ["financial-services", "banking", "wealth-management", "donor-advised-funds"]
C.q(1, "AI inventory", "Do you maintain an inventory of every AI system, model and AI-enabled feature used to deliver or support the services you provide to us?",
    "Customer needs to know where AI touches its data and processes to govern its own AI risk.",
    "Unknown AI use creates unassessed data, accuracy and security exposure.",
    ["SRC-NIST-AI-RMF-1.0|GOVERN 1.6|d", "SRC-ISO-42001-2023||r", "SRC-CSA-AICM||r", "SRC-SA-SIG||r"],
    "industry-convention", "high",
    ["Provide a list of all AI and machine learning components in your solution.", "Describe the AI systems that are part of the service, including third-party models."])
C.q(1, "AI inventory", "Does your AI inventory include AI used internally to build, test and operate the service, such as AI coding agents and AI operations assistants, and not only AI features exposed to customers?",
    "Customers increasingly ask how vendor software is produced, because AI-written code and AI operators change the risk profile.",
    "Internal AI use with access to source code, secrets or production goes unassessed.",
    ["SRC-NIST-SP800-218A||r", "SRC-NIST-AI-RMF-1.0|GOVERN 1.6|r"],
    "customer-preference", "high",
    ["Do your developers use AI coding assistants? Which ones?", "Is generative AI used in your software development lifecycle?"])
C.q(1, "AI inventory", "For each AI use, which data classes can it access, which provider hosts the model, and which model version is in use?",
    "Data exposure depends on what each AI component can read and where it is processed.",
    "Customer data reaches a model provider or model version the customer has not assessed.",
    ["SRC-NIST-AI-600-1||r", "SRC-CSA-AICM||r"],
    "customer-preference", "medium")
C.q(1, "AI inventory", "How do you detect and prevent unapproved AI tools (shadow AI) receiving customer data from your personnel or contractors?",
    "Unsanctioned AI tools are a common data leakage path.",
    "Confidential customer data entered into consumer AI tools with training-permissive terms.",
    ["SRC-NIST-AI-600-1||r", "SRC-ISO-42001-2023|A.9|r"],
    "industry-convention", "high",
    ["Do you block or monitor employee use of public generative AI services?"])
C.q(1, "AI inventory", "When a model version, provider, prompt or tool changes, how quickly is the AI inventory updated, and how is completeness verified?",
    "A stale inventory gives false assurance.",
    "Changes to AI behavior go unrecorded and unreviewed.",
    ["SRC-NIST-AI-RMF-1.0|GOVERN 1.6|r", "SRC-ECH-UNB-BASELINE|AIN-027"],
    "customer-preference", "medium")
C.q(1, "AI inventory", "Can you give us a customer-specific list of the AI components and AI providers that process our data?",
    "Customer must record vendor AI use in its own AI inventory and regulatory filings.",
    "Customer cannot meet its own inventory or disclosure obligations.",
    ["SRC-NAIC-AI-BULLETIN||r", "SRC-NIST-AI-RMF-1.0|GOVERN 6.1|r"],
    "customer-preference", "medium", industries=["insurance"] + FIN)

C.q(2, "AI policy", "Do you have a formally approved policy governing the development, procurement and use of AI? Who approved it and when was it last reviewed?",
    "A formal policy shows management commitment and sets enforceable rules.",
    "AI use is governed by individual judgment with no accountable standard.",
    ["SRC-ISO-42001-2023|5.2|d", "SRC-NIST-AI-RMF-1.0|GOVERN 1.2|r", "SRC-CSA-AICM||r", "SRC-SA-SIG||r"],
    "industry-convention", "high",
    ["Please provide your AI governance policy.", "Does your organization have an acceptable use policy for artificial intelligence?"])
C.q(2, "AI policy", "Who is the accountable executive for AI risk, and how does AI risk reach senior management or the board?",
    "Accountability must sit with a named person with authority.",
    "AI risk decisions are made without accountable ownership.",
    ["SRC-NIST-AI-RMF-1.0|GOVERN 2.1|r", "SRC-ISO-42001-2023|5.3|r"],
    "industry-convention", "medium")
C.q(2, "AI policy", "What rules govern your personnel entering our confidential data into AI tools, and how are those rules enforced technically?",
    "Customer data handling rules must extend to AI tools.",
    "Customer data disclosed to AI providers outside contractual protections.",
    ["SRC-NIST-AI-600-1||r", "SRC-ISO-27001-2022|A.5.10|r"],
    "contractual-common", "high")
C.q(2, "AI policy", "What AI literacy training do your personnel and agent operators receive, and how is completion tracked?",
    "Staff who use or oversee AI must understand its limits, including automation bias.",
    "Untrained operators over-trust AI outputs or misuse AI tools.",
    ["SRC-EU-AI-ACT|Art. 4|d", "SRC-NIST-AI-RMF-1.0|GOVERN 2.2|r"],
    "legal-regulatory", "medium", jurisdictions=["EU"],
    authority="EU AI Act national market surveillance authorities",
    scope="Article 4 applies to providers and deployers of AI systems within the AI Act's scope; applicability to Echelon depends on EU exposure, which is not established.")
C.q(2, "AI policy", "How are exceptions to your AI policy requested, approved, time-limited and recorded?",
    "Exceptions are where policy fails in practice.",
    "Permanent undocumented exceptions erode the policy.",
    ["SRC-ECH-UNB-SOC2-DIRECTIVE|SOC2-033", "SRC-ISO-42001-2023||r"],
    "industry-convention", "low")

C.q(3, "Framework alignment", "Have you aligned your AI risk management to the NIST AI Risk Management Framework, including the Generative AI Profile? Can you share the mapping?",
    "A recognized framework gives the customer a common reference for completeness.",
    "Material AI risk categories are not considered.",
    ["SRC-NIST-AI-RMF-1.0||d", "SRC-NIST-AI-600-1||d"],
    "industry-convention", "medium",
    ["Which AI risk management framework does your organization follow?"])
C.q(3, "Framework alignment", "Are you certified to ISO/IEC 42001, and if not, do you plan to be? What scope and timeline?",
    "Certification offers independent assurance of an AI management system.",
    "Customer relies on unverified vendor claims about AI governance.",
    ["SRC-ISO-42001-2023||d", "SRC-ISO-17021-1||r"],
    "certification-criteria", "medium",
    ["Do you hold any AI-related certifications?"])
C.q(3, "Framework alignment", "Has any independent party assessed your AI governance or AI controls, for example a SOC 2 examination covering AI agents or an ISO/IEC 42001 audit?",
    "Independent assessment distinguishes operating controls from intentions.",
    "AI controls described in questionnaires are not operating.",
    ["SRC-AICPA-TSC||r", "SRC-ISO-42001-2023||r", "SRC-ECH-UNB-SOC2-DIRECTIVE|SOC2-017"],
    "customer-preference", "high")
C.q(3, "Framework alignment", "Do you map your AI controls to the CSA AI Controls Matrix or a similar control catalog that we can compare across vendors?",
    "Comparable control catalogs speed vendor assessment.",
    "Inconsistent vendor AI assessments across the customer portfolio.",
    ["SRC-CSA-AICM||d", "SRC-OWASP-AI-EXCHANGE||r"],
    "customer-preference", "low")

C.q(4, "AI risk assessment", "Before deploying an AI capability, do you perform a documented risk assessment covering accuracy, security, privacy, bias and misuse? Who approves it?",
    "AI risks should be assessed before exposure, not after an incident.",
    "Harmful or insecure AI capabilities reach production unassessed.",
    ["SRC-NIST-AI-RMF-1.0|MAP 1.1|r", "SRC-ISO-23894-2023||d", "SRC-ISO-42001-2023|6.1.4|r"],
    "industry-convention", "high",
    ["Describe your AI risk assessment process.", "How do you assess risks of new AI use cases?"])
C.q(4, "AI impact assessment", "Do you assess the impact of your AI systems on individuals affected by them, such as donors, advisors, grantees and employees?",
    "AI that affects people can cause harms that a security-only review misses.",
    "Unfair or opaque treatment of individuals by automated processes.",
    ["SRC-ISO-42005||d", "SRC-COLORADO-AI-ACT||r", "SRC-NIST-AI-RMF-1.0|MAP 5.1|r"],
    "industry-convention", "medium", industries=["donor-advised-funds", "nonprofit", "financial-services"])
C.q(4, "Consequential decisions", "Is AI used to make, or to be a substantial factor in, any decision about an individual's eligibility, access to services, financial outcome or employment?",
    "Consequential automated decisions attract specific legal duties and higher scrutiny.",
    "Unlawful or unfair automated decisions and the liability that follows.",
    ["SRC-COLORADO-AI-ACT||r", "SRC-GDPR|Art. 22|d", "SRC-US-STATE-AI-LAWS||r", "SRC-ECH-UNB-BASELINE|CNV-AIO-001"],
    "legal-regulatory", "critical", jurisdictions=["US-state:CO", "US-states", "EU"],
    authority="Colorado Attorney General; EU data protection authorities",
    scope="Legal duties arise only if AI is a substantial factor in such decisions; Unbound design intends that it is not, which requires counsel confirmation.")
C.q(4, "Bias testing", "How do you test automated matching or scoring, for example sanctions name matching, for higher false-alert rates on particular name origins or groups?",
    "Disparate false alerts burden specific donors and grantees and can be discriminatory.",
    "Systematic delay or denial for people with names of certain origins.",
    ["SRC-ECH-UNB-BASELINE|CNV-GRT-006", "SRC-NIST-AI-RMF-1.0|MEASURE 2.11|r", "SRC-NIST-AI-600-1||r"],
    "customer-preference", "medium", industries=["donor-advised-funds", "banking", "financial-services"], products=["unbound"])
C.q(4, "Reassessment", "What events cause an AI risk assessment to be repeated, for example a model change, new data source, new use or incident?",
    "Risk changes when the model, data or use changes.",
    "Assessment becomes stale while the AI behavior changes.",
    ["SRC-NIST-AI-RMF-1.0|MANAGE 4.1|r", "SRC-ISO-42001-2023||r"],
    "industry-convention", "medium")

C.q(5, "Provider due diligence", "Which third-party AI model providers do you use, and what due diligence did you perform on each before use?",
    "AI providers are critical vendors with access to customer content.",
    "Reliance on a provider with weak security, poor data terms or unstable service.",
    ["SRC-NIST-AI-RMF-1.0|GOVERN 6.1|d", "SRC-ISO-42001-2023|A.10|r", "SRC-INTERAGENCY-TPRM-2023||r", "SRC-SA-SIG||r"],
    "industry-convention", "high",
    ["List the foundation models and AI vendors used in your product."])
C.q(5, "Provider assurance", "Do you obtain and review SOC 2 or equivalent assurance reports from your AI providers, and how do you implement their complementary user entity controls?",
    "Provider assurance only holds if the user entity controls are operated.",
    "Gaps between provider controls and Echelon's assumed controls.",
    ["SRC-AICPA-SOC2-GUIDE||r", "SRC-ECH-UNB-BASELINE|RR-REQ-X-073-r2"],
    "industry-convention", "medium")
C.q(5, "Model documentation", "Before adopting a model, do you review its documentation, such as system cards, evaluation results and known limitations, against your intended use?",
    "Model fitness depends on documented limitations.",
    "A model is used outside its demonstrated competence.",
    ["SRC-NIST-AI-600-1||r", "SRC-EU-AI-ACT|Art. 53|r"],
    "customer-preference", "medium")
C.q(5, "Model change", "How do you detect and control provider-initiated model updates or deprecations so that model behavior does not change in production without your review?",
    "Silent model changes alter outputs without any vendor change record.",
    "Regression in accuracy or safety after an unannounced provider update.",
    ["SRC-ECH-UNB-BASELINE|RR-AIN-027-r1", "SRC-NIST-AI-RMF-1.0|MANAGE 3.1|d"],
    "customer-preference", "high")
C.q(5, "Model licensing", "If you use open-weight or third-party models, how do you assess their license and acceptable use terms against your commercial use?",
    "License breaches can force removal of a component the service depends on.",
    "Legal exposure or forced replacement of a model.",
    ["SRC-ECH-UNB-BASELINE|CNV-GOV-009", "SRC-NIST-AI-600-1||r"],
    "industry-convention", "low")

C.q(6, "Provider data terms", "Do the AI providers you use retain prompts and outputs that contain our data, and for how long?",
    "Retained prompts extend the footprint of customer data.",
    "Customer data persists at a provider beyond the customer's retention rules.",
    ["SRC-NIST-AI-600-1||r", "SRC-GDPR|Art. 28|r"],
    "contractual-common", "high",
    ["What is your AI vendor's data retention policy for inputs and outputs?"])
C.q(6, "Training use", "Is our data used by you or any AI provider to train, fine-tune or improve models? Is that prohibited by contract?",
    "Customers commonly prohibit training on their data to protect confidentiality and IP.",
    "Customer or donor data memorized and exposed through a model.",
    ["SRC-ISO-42001-2023|A.7|r", "SRC-NIST-AI-600-1||r", "SRC-GDPR|Art. 28|r"],
    "contractual-common", "critical",
    ["Will customer data be used to train AI models?", "Do you opt out of model training with your AI providers?"])
C.q(6, "Provider human review", "Do AI provider terms allow provider staff to review prompts for abuse monitoring, and have you obtained zero-retention or opt-out terms where available?",
    "Human review by a provider is a disclosure of customer content.",
    "Unexpected human access to confidential donor or financial data.",
    ["SRC-NIST-AI-600-1||r"],
    "customer-preference", "medium")
C.q(6, "Echelon training use", "Will you use our data to train, tune or evaluate your own models, agents or prompts, including building evaluation sets?",
    "Evaluation and tuning uses are often overlooked in no-training commitments.",
    "Customer data reused across customers through evaluation sets or tuned prompts.",
    ["SRC-ECH-BUSINESS-PLAN|10-technology-data-and-ai/10.04", "SRC-ECH-UNB-SOC2-DIRECTIVE|SOC2-028"],
    "contractual-common", "high")

